  const dateFmt = (v, opts) => new Intl.DateTimeFormat("vi-VN", {
      timeZone: "Asia/Ho_Chi_Minh",
      ...opts
    }).format(new Date(v)),
    time = v => dateFmt(v, {
      hour: "2-digit",
      minute: "2-digit",
      day: "2-digit",
      month: "2-digit",
      year: "numeric"
    }),
    day = v => new Date(+new Date(v) + 7 * 3600000).toISOString().slice(0, 10);
  const id = () => crypto.randomUUID(),
    root = $("#shop"),
    nativeNow = () => new Date().toISOString();
  let staff = false;
  let staffProfiles = [];
  // A login stays usable in this tab even when an embedded browser blocks cookies.
  let tabToken = "", currentUsername = "";
  function shopFetch(path, options={}) {
    const headers = new Headers(options.headers);
    if (tabToken) headers.set("X-Shop-Session",tabToken);
    return fetch(path,{...options,headers});
  }
  async function auth(action,values={}) {
    const response=await shopFetch("/api/account",action?{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,...values})}:{cache:"no-store"});
    const result=await response.json();
    if (!response.ok) throw Error(result.error || "Không thể kết nối tài khoản.");
    return result;
  }
  async function refreshAccounts() { staffProfiles=(await auth()).staff; }
  function passwordVisibility(button,visible) {
    const input=button.parentElement.querySelector("input");
    const start=input.selectionStart,end=input.selectionEnd,direction=input.selectionDirection;
    input.type=visible?"text":"password";
    if (start!==null && end!==null) input.setSelectionRange(start,end,direction || "none");
    button.setAttribute("aria-pressed",String(visible));
    button.title=visible?"Ẩn mật khẩu":"Hiện mật khẩu";
  }
  async function logout() {
    if (busy) return;
    busy=true;
    const overlay=document.createElement("dialog");
    overlay.className="logout-scene";
    overlay.setAttribute("aria-labelledby","logout-status");
    overlay.innerHTML='<div><img alt="" width="320" height="180" src="'+(staff?"/logout-ride.svg":"/logout-shutter.svg")+'"><p id="logout-status" role="status">'+(staff?"Đang kết thúc ca bán hàng…":"Đang đóng cửa hàng…")+'</p></div>';
    overlay.addEventListener("cancel",event=>event.preventDefault());
    document.body.append(overlay);
    try {
      overlay.showModal();
      const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      await Promise.all([auth("logout"),reduced?Promise.resolve():new Promise(done=>setTimeout(done,staff?1700:1600))]);
      tabToken="";
      location.replace("/");
    } finally {
      overlay.remove();
      busy=false;
    }
  }
  function credentials(create,profile) {
    return field("Tên tài khoản","username","text",profile?.username || "","required minlength=3 maxlength=50 autocapitalize=none spellcheck=false autocomplete=username")+
      passwordField(profile?"Mật khẩu mới (để trống nếu giữ mật khẩu cũ)":"Mật khẩu","password",create?"new-password":"current-password",!profile);
  }
