  async function load() {
    const r = await shopFetch("/api/ledger", {
      cache: "no-store"
    });
    if (r.status===403) throw Error("Phiên đăng nhập đã hết hoặc chưa được xác nhận. Hãy mở WorkHard trong tab riêng và đăng nhập lại.");
    if (!r.ok) throw Error("Không thể tải dữ liệu.");
    const v = await r.json();
    acceptState(v);
  }
  let syncEpoch=0, syncRunning=false, syncNeedsRender=false, syncDirty=false, syncTick=0;
  let accountSnapshot=null;
  let syncNoticeTimer;
  function syncNotice(message){
    let notice=document.getElementById("live-sync-notice");
    if(!notice){
      notice=document.createElement("div");notice.id="live-sync-notice";
      notice.setAttribute("role","status");notice.setAttribute("aria-live","polite");
      document.body.append(notice);
    }
    notice.textContent=message;
    clearTimeout(syncNoticeTimer);syncNoticeTimer=setTimeout(()=>notice.remove(),5500);
  }
  function refreshSyncedView(){
    if(!syncNeedsRender||busy||syncDirty||document.querySelector("dialog[open]")||
      document.activeElement?.matches("input,textarea,select,[contenteditable=true]"))return;
    const x=window.scrollX,y=window.scrollY;
    render();window.scrollTo(x,y);
  }
  async function syncStore(){
    if(syncRunning||busy||document.hidden||!root.querySelector("main"))return;
    syncRunning=true;
    const epoch=syncEpoch,user=myKey,initialVersion=version;
    try{
      const response=await shopFetch("/api/ledger?since="+encodeURIComponent(initialVersion),{cache:"no-store",signal:AbortSignal.timeout(12000)});
      if(busy||epoch!==syncEpoch||user!==myKey)return;
      if(response.status===403){syncNotice("Phiên đăng nhập đã hết. Vui lòng đăng nhập lại.");return;}
      if(response.status!==204){
        if(!response.ok)throw Error("sync");
        const state=await response.json();
        if(busy||epoch!==syncEpoch||user!==myKey)return;
        if(state.version>version){
          acceptState(state);syncNeedsRender=true;
        }
      }
      if(!staff&&++syncTick%5===0){
        const accountEpoch=syncEpoch;
        const response=await shopFetch("/api/account",{cache:"no-store",signal:AbortSignal.timeout(12000)});
        if(!response.ok)throw Error("account sync");
        const state=await response.json();
        if(busy||accountEpoch!==syncEpoch||user!==myKey)return;
        if(!state.current){syncNotice("Phiên đăng nhập đã hết. Vui lòng đăng nhập lại.");return;}
        const snapshot=JSON.stringify(state.staff);
        if(accountSnapshot!==null&&snapshot!==accountSnapshot){
          syncNotice("Danh sách tài khoản nhân viên vừa được cập nhật");syncNeedsRender=true;
        }
        accountSnapshot=snapshot;staffProfiles=state.staff;
      }
      refreshSyncedView();
    }catch(error){
      if(root.querySelector("main"))syncNotice("Đang kết nối lại để cập nhật dữ liệu…");
    }finally{syncRunning=false;}
  }
