  window.addEventListener("focus",()=>void syncStore());
  setInterval(()=>void syncStore(),3000);
  const staffNav={"Bán hàng":"sale","Đơn đã bán":"clock","Thu nợ khách hàng":"cash","Chấm công":"clock","Đơn xin nghỉ":"users","Yêu cầu hóa đơn":"settings"};
