  function attendance(){
    const shifts=db.shifts||[], leaves=db.leaves||[];
    const people=new Map();
    if(!staff){
      for(const row of [...shifts,...leaves])people.set(row.user,row.person);
      for(const p of staffProfiles.filter(p=>p.approved))people.set(p.employeeKey||"account:"+p.username,(p.fullName||p.username)+" · "+p.username);
    }
    if(!people.has(attendanceEmployee))attendanceEmployee="";
    const employee=staff?myKey:attendanceEmployee;
    const matches=r=>!employee||r.user===employee;
    const visibleShifts=shifts.filter(matches),visibleLeaves=leaves.filter(r=>matches(r)&&r.status==="Đã duyệt");
    const manual=(db.manualAttendance||[]).filter(matches),overridden=new Set(manual.map(r=>r.user+":"+r.day));
    const calendarShifts=visibleShifts.filter(r=>!overridden.has(r.user+":"+r.day)).concat(manual.filter(r=>r.status!=="Nghỉ"));
    const calendarLeaves=visibleLeaves.filter(r=>!overridden.has(r.user+":"+r.day)).concat(manual.filter(r=>r.status!=="Đi làm"));
    const picker=staff?"":sel("Xem lịch của","attendanceEmployee",opt("","Tất cả nhân viên")+Array.from(people,([key,label])=>'<option value="'+esc(key)+'"'+(key===employee?' selected':'')+'>'+esc(label)+'</option>').join(""));
    const open=staff&&visibleShifts.find(r=>!r.out);
    const rows=visibleShifts.filter(r=>r.day===workDay).slice().reverse().map(r=>[esc(r.person),time(r.at),r.out?time(r.out):stateLabel("Chưa có giờ ra"),r.checkin?button("Xem ảnh & vị trí","viewCheckin:"+r.id,"link"):"Ca cũ · Chưa có ảnh"]);
    return head("NHÂN VIÊN",page,staff?"Ghi nhận thời gian vào ca và kết thúc ca.":"Theo dõi ngày làm và ngày nghỉ của nhân viên.")+
      (staff?panel("Ca làm việc của tôi",'<p class="summary">'+(open?"Đang làm việc từ "+time(open.at):"Bạn chưa mở ca.")+'</p>'+actions(open?"Kết thúc ca":"Vào ca",open?"shiftOut":"shiftIn")):"")+
      (!staff?panel("Quản lý điểm danh",'<p>'+(db.storeLocation?"Đã lưu vị trí cửa hàng. Nhân viên chỉ vào ca trong phạm vi 100 m.":"Chưa đặt vị trí cửa hàng — nhân viên chưa thể tự vào ca.")+'</p>'+button("Kiểm tra / cập nhật vị trí","reviewStoreLocation")+button("Điểm danh thủ công","manualAttendance","btn")):"")+
      attendanceCalendar(calendarShifts,calendarLeaves,picker)+
      (manual.some(r=>r.day===workDay)?panel("Điểm danh do chủ xác nhận",table(["Nhân viên","Trạng thái","Ghi chú","Người xác nhận","Cập nhật"],manual.filter(r=>r.day===workDay).map(r=>[esc(r.person),esc(r.status),esc(r.note),esc(r.by),time(r.at)]))):"")+
      panel("Chi tiết ngày "+workDay.split("-").reverse().join("/"),visibleLeaves.filter(r=>r.day===workDay).map(r=>'<p class="summary">'+esc(r.person)+' · Nghỉ đã duyệt · '+esc(r.slot)+'</p>').join("")+table(["Nhân viên","Vào ca","Ra ca","Check-in"],rows,"Chưa có lượt điểm danh trong ngày."));
  }
