  const head = (tag, title, desc, act = "") => '<div class="head"><div><div class="eyebrow">' + tag + '</div><h1>' + title + '</h1><p>' + desc + '</p></div>' + act + '</div>';
  const panel = (title, body, extra = "") => '<section class="panel space"><div class="row"><h2>' + title + '</h2>' + extra + '</div>' + body + '</section>';
  // Receipts and stock lots are appended together in the same transaction.
  // Replay sales in posting order so earlier sales keep their original costs.
  function costBySale(ledger) {
    const inventory = new Map(ledger.products.map(p => [p.id, {
      product: p, batches: [], rolls: new Map(), next: 0
    }]));
    for (const receipt of ledger.receipts.flatMap(receiptLines)) {
      const item = inventory.get(receipt.product);
      if (!item) continue;
      const lot = item.product.lots[item.batches.length];
      const batch = { quantity: receipt.qty, cost: receipt.cost, used: 0 };
      item.batches.push(batch);
      if (lot) item.rolls.set(lot.id, batch);
    }
    const costs = new Map();
    for (const sale of ledger.sales) {
      let cost = 0;
      for (const line of sale.lines) {
        const item = inventory.get(line.product);
        if(line.allocations){
          for(const allocation of line.allocations){
            const batch=item?.rolls.get(allocation.lot);
            if(!batch || !(batch.quantity>0)){cost=NaN;break;}
            const before=Math.round(batch.cost*batch.used/batch.quantity);
            batch.used=round(batch.used+allocation.qty);
            cost+=Math.round(batch.cost*batch.used/batch.quantity)-before;
          }
          continue;
        }
        let left = line.base;
        while (left > 0) {
          const batch = line.lot ? item?.rolls.get(line.lot) : item?.batches[item.next];
          if (!batch || !(batch.quantity > batch.used) || !Number.isFinite(batch.cost)) {
            cost = NaN;
            break;
          }
          const take = Math.min(left, round(batch.quantity - batch.used));
          const before = Math.round(batch.cost * batch.used / batch.quantity);
          batch.used = round(batch.used + take);
          cost += Math.round(batch.cost * batch.used / batch.quantity) - before;
          left = round(left - take);
          if (!line.lot && batch.used >= batch.quantity) item.next++;
        }
      }
      costs.set(sale.id, cost);
    }
    return costs;
  }
