  async function prepareProductPhoto(file){
    if(!["image/jpeg","image/png","image/webp"].includes(file.type))throw Error("Chọn ảnh JPG, PNG hoặc WebP.");
    if(file.size>12*1024*1024)throw Error("Ảnh tối đa 12 MB. Vui lòng chọn ảnh nhỏ hơn.");
    const bitmap=await createImageBitmap(file);
    try{
      const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));
      const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
      const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);
      const blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/jpeg",.82));
      if(!blob||blob.size>2*1024*1024)throw Error("Ảnh quá lớn sau khi xử lý. Hãy chọn ảnh khác.");
      return blob;
    }finally{bitmap.close();}
  }
