  function updateMatches(box) {
    const query = searchName(box.querySelector(".product-query").value);
    const results = box.querySelector(".product-results");
    const resultLimit = Number(box.dataset.limit || 12);
    results.hidden = !query;
    if (!query) { results.innerHTML = ""; return; }
    const terms = query.split(/\s+/);
    const groups=new Map();
    for (const p of activeProducts()) {
      const name=searchName(p.name+" "+(p.brand||""));
      if (!terms.every(term=>name.includes(term))) continue;
      const key=productFamilyKey(p);
      if (!groups.has(key)) groups.set(key,[]);
      groups.get(key).push(p);
    }
    const matches=[...groups.values()];
    results.innerHTML=matches.slice(0,resultLimit).map(family=>{
      const p=family[0], photo=family.find(v=>v.image)||p;
      const hint=family.length===1 ? [p.brand,p.width?"Khổ "+num(p.width)+" m":"",money(p.price)+" / "+(p.width?"m²":p.unit),"Tồn "+num(stock(p))+" "+p.unit].filter(Boolean).join(" · ")
        : family.length+" quy cách · Chọn khổ / quy cách";
      return button(productPhoto(photo)+"<span><b>"+esc(productFamilyLabel(p))+"</b><small>"+esc(hint)+"</small></span>","pick-sale:"+p.id,"sale-option");
    }).join("")+(matches.length>resultLimit?button("Xem thêm kết quả","more-sales","link"):"");
    if (!matches.length) results.textContent = "Không tìm thấy sản phẩm phù hợp.";
  }
  function chooseProduct(box,key) {
    const p = product(key);
    if (!p || p.archived) return;
    box.querySelector('input[type=hidden]').value = key;
    box.querySelector(".product-query").value = variantName(p);
    box.querySelector(".product-results").hidden = true;
    const row = box.closest(".intake-row");
    let quantity;
    if (row) {
      updateIntakeRow(row);
      intakeTotals();
      quantity = row.querySelector('[name=intakeQty]');
    } else {
      tradeFields(true);
      quantity = $('[name=quantity]');
    }
    quantity.focus();
    quantity.select();
  }
  const receiptDay = r => r.receivedOn || day(r.at);
  const receiptTime = r => Date.parse(receiptDay(r) + "T00:00:00+07:00");
  function receiptHeader() {
    const suppliers = db.suppliers || [];
    return '<div class="forms">' + field("Ngày nhập hàng", "receivedOn", "date", day(Date.now()), 'required max="' + day(Date.now()) + '"') +
      sel("Nhà cung cấp", "supplier", opt("", "Chưa ghi nhà cung cấp") + opt("new", "＋ Thêm cơ sở / cửa hàng mới") +
        suppliers.map(v => opt(v.id, v.name + (v.phone ? " · " + v.phone : ""))).join("")) + '</div><div id="supplierInfo"></div>';
  }
  function supplierInfo() {
    const key = $('[name=supplier]').value;
    const supplier = db.suppliers?.find(v => v.id === key);
    $("#supplierInfo").innerHTML = key === "new" ? '<div class="forms">' +
      field("Tên cơ sở / cửa hàng", "supplierName") + field("Số điện thoại", "supplierPhone", "tel", "", "") +
      field("Địa chỉ", "supplierAddress", "text", "", "") + '</div>' :
      supplier ? '<p class="summary">' + [supplier.name, supplier.phone, supplier.address].filter(Boolean).map(esc).join(" · ") + '</p>' : "";
  }
  function receiptSupplier(d, f) {
    if (!f.supplier) return null;
    if (f.supplier !== "new") {
      const found = d.suppliers?.find(v => v.id === f.supplier);
      if (!found) throw Error("Vui lòng chọn lại nhà cung cấp.");
      return { ...found };
    }
    const supplier = { id: id(), name: f.supplierName.trim(), phone: f.supplierPhone.trim(), address: f.supplierAddress.trim() };
    if (!supplier.name) throw Error("Nhập tên cơ sở hoặc cửa hàng cung cấp.");
    (d.suppliers ||= []).push(supplier);
    return { ...supplier };
  }
  let receiptPeriod = "all", receiptAnchor = day(Date.now());
  const supplierPaid = r => total(r.outgoing, payment => payment.amount);
  const balance = r => r.cost - supplierPaid(r);
  function recordOutgoing(r, amount, method, initial) {
    if (initial === Array.isArray(r.outgoing)) throw Error("Trạng thái thanh toán đã thay đổi.");
    const due = initial ? r.cost : balance(r);
    if (!Number.isSafeInteger(amount) || amount < (initial ? 0 : 1) || amount > due) throw Error("Số tiền không hợp lệ hoặc vượt tiền còn phải trả.");
    if (amount < due && !r.supplier) throw Error("Hãy chọn nhà cung cấp để ghi nợ.");
    if (initial) r.outgoing = [];
    if (amount) r.outgoing.push({amount, method, at: nativeNow(), initial});
  }
  const paymentMethod = () => sel("Phương thức chi", "outMethod", opt("Tiền mặt", "Tiền mặt") + opt("Chuyển khoản", "Chuyển khoản"));
  function receiptLines(receipt) { return receipt.lines || [receipt]; }
  function itemName(line) { return line.name ?? product(line.product)?.name ?? "Sản phẩm"; }
  function receiptTitle(r) {
    return r.lines ? r.code + " · " + r.lines.length + " dòng hàng" : itemName(r);
  }
  function intakeRow() {
    return '<fieldset class="intake-row"><legend>Mặt hàng</legend><div class="forms">' +
      productPicker("intakeProduct") +
      '<div class="intake-fields"></div></div><div class="row"><small class="line-total"></small>' +
      button("Bỏ dòng","dropIntake","link")+'</div></fieldset>';
  }
  function intakeValues(row) {
    const value = key => inputValue(row.querySelector('[name="'+key+'"]'));
    return {product:value("intakeProduct"),unit:value("intakeUnit"),quantity:value("intakeQty"),price:value("intakePrice")};
  }
  // Index the latest receipt by effective date, retaining posting order for ties.
  let priceIndexLedger, priceIndexDate, priceIndex;
  function priorPrices(ledger, date) {
    if (ledger === priceIndexLedger && date === priceIndexDate) return priceIndex;
    const index = new Map();
    for (const receipt of ledger.receipts) {
      const at = receiptDay(receipt);
      if (at > date) continue;
      for (const line of receiptLines(receipt)) {
        if (index.get(line.product)?.at > at) continue;
        index.set(line.product, {at, line, supplier:receipt.supplier?.name || ""});
      }
    }
    priceIndexLedger=ledger; priceIndexDate=date; priceIndex=index;
    return index;
  }
  function priorPrice(entry,p,pack) {
    if (!entry) return null;
    const l=entry.line;
    if (!(l.qty>0 && l.quantity>0)) return null;
    const width=l.width || p.width || 1;
    const basePrice=l.price!=null ? (p.width ? l.price : l.price*l.quantity/l.qty) : l.cost/(l.qty*width);
    return {at:entry.at,supplier:entry.supplier,price:round(basePrice*(pack ? p.factor : 1))};
  }
  function priceChange(previous,current) {
    const delta=round(Number(current)-previous);
    if (!delta) return "Giá không đổi";
    return (delta>0?"Tăng ":"Giảm ")+money(Math.abs(delta))+
      (previous>0?" ("+num(Math.round(Math.abs(delta)/previous*10000)/100)+"%)":"");
  }
  function lastSoldPrice(p, factor) {
    for (let i=db.sales.length-1;i>=0;i--) {
      const sale=db.sales[i];
      const line=sale.lines.findLast(l=>l.product===p.id && Number.isFinite(l.price) && l.base>0);
      if (line) return {price:round((p.width ? line.price : line.price*line.quantity/line.base)*factor),at:day(sale.at)};
    }
    return null;
  }
  function retailComparison(ref, value) {
    const describe=(label, price)=>label+" "+money(price)+" / "+ref.unit+
      (value!=="" && Number(value)>=0 ? " · "+priceChange(price,value) : "");
    const lines=[describe("Giá niêm yết hiện tại:",ref.current)];
    if (ref.last) lines.push(describe("Lần bán gần nhất ("+ref.last.at.split("-").reverse().join("/")+"):",ref.last.price));
    return lines.map(esc).join("<br>");
  }
  function costHint(cost,label,unit,retail) {
    if (cost == null || !Number.isFinite(cost)) return "Chưa có giá nhập để so sánh.";
    const text=esc(label+" "+money(cost)+" / "+unit);
    const diff=round(cost-Number(retail));
    return retail!=="" && diff>0 ? text+'<br><strong class="below-cost">⚠ Bán dưới giá nhập · Thấp hơn '+esc(money(diff)+" / "+unit)+'</strong>' : text;
  }
  function catalogCost(p,pack) {
    return priorPrice(priorPrices(db,day(Date.now())).get(p.id),p,pack)?.price ?? null;
  }
  function saleCostHint() {
    const el=$("#tradeFields .retail-cost");
    if (!el) return;
    const p=product($('[name=product]').value),pack=$('[name=unit]').value==="pack";
    let cost=catalogCost(p,pack),label="Giá nhập gần nhất:";
    if (p.width && $('[name=lot]')?.value) {
      const index=p.lots.findIndex(l=>l.id===$('[name=lot]').value);
      const line=db.receipts.flatMap(receiptLines).filter(l=>l.product===p.id)[index];
      cost=line ? priorPrice({line},p,false)?.price : null;
      label="Giá nhập cuộn đã chọn:";
    }
    el.innerHTML=costHint(cost,label,p.width?"m²":pack?p.pack:p.unit,inputValue($('#tradeFields [name=price]')));
  }
  function retailField(p,name,label,value,attrs,pack=false) {
    const input=field(label,name,"number",value,attrs);
    if (staff) return input;
    if (!p) return input+'<small>Giá bán đầu tiên · Chưa có giá nhập để so sánh.</small>';
    const factor=pack?p.factor:1;
    const ref={cost:catalogCost(p,pack),current:Math.round(p.price*factor),unit:p.width?"m²":pack?p.pack:p.unit,last:lastSoldPrice(p,factor)};
    return '<div class="retail-price" data-ref="'+esc(JSON.stringify(ref))+'">'+input+
      '<small class="retail-change" aria-live="polite">'+retailComparison(ref,value)+'</small>'+(name==="newRetail"?"":'<small class="retail-cost" aria-live="polite">'+costHint(ref.cost,"Giá nhập gần nhất:",ref.unit,value)+'</small>')+'</div>';
  }
  function comparisonText(prior,price,unit) {
    if (!prior) return "Chưa có giá nhập trước đó cho mặt hàng này.";
    const ref="Lần trước "+prior.at.split("-").reverse().join("/")+(prior.supplier?" · "+prior.supplier:"")+
      ": "+money(prior.price)+" / "+unit;
    return price==="" ? ref : ref+" · "+priceChange(prior.price,price)+" / "+unit;
  }
  function updateIntakeRow(row) {
    const f=intakeValues(row), p=product(f.product);
    row.querySelector(".intake-fields").innerHTML = p ? '<div class="forms">'+
      sel("Đơn vị nhập","intakeUnit",opt("base",p.unit)+(p.pack?opt("pack",p.pack):"")) +
      field(p.width?"Chiều dài cuộn (m)":"Số lượng","intakeQty","number",1,"required min=0.001 step=0.001")+
      field("Giá nhập / "+esc(p.width?"m²":p.unit)+" (₫)","intakePrice","number","","required min=0 step=1")+'</div><p class="summary cost-comparison"></p><details class="space"><summary>Giá bán hiện tại: '+money(p.price)+' / '+esc(p.width?"m²":p.unit)+' · Chỉnh giá bán</summary>'+
      retailField(p,"newRetail","Giá bán mới / "+esc(p.width?"m²":p.unit)+" (₫)","","min=1 step=1 placeholder=\"Để trống để giữ giá hiện tại\"")+'</details><small class="intake-cost retail-cost" aria-live="polite"></small>':"";
  }
  function intakeTotals() {
    let sum=0;
    for (const row of document.querySelectorAll(".intake-row")) {
      const f=intakeValues(row), p=product(f.product);
      const value=Math.round(Number(f.quantity)*Number(f.price)*(p?.width||1));
      sum+=value;
      const hint=row.querySelector(".cost-comparison");
      if (p && hint) {
        const retail=inputValue(row.querySelector('[name=newRetail]'));
        const unit=p.width?"m²":p.unit;
        const entry=priorPrices(db,$('[name=receivedOn]').value).get(p.id);
        const cost=f.price==="" ? priorPrice(entry,p,false)?.price : round(Number(f.price)/(f.unit==="pack"?p.factor:1));
        row.querySelector(".intake-cost").innerHTML=costHint(cost,f.price===""?"Giá nhập gần nhất:":"Giá nhập phiếu này:",unit,retail===""?p.price:retail);
        hint.textContent=comparisonText(priorPrice(entry,p,f.unit==="pack"),f.price,p.width?"m²":f.unit==="pack"?p.pack:p.unit);
      }
      row.querySelector(".line-total").textContent=(p?.width?"Khổ "+num(p.width)+" m · ":"")+"Thành tiền "+money(value);
    }
    $("#intakeTotal").textContent="Tổng phiếu nhập · "+money(sum);
  }
  function postReceipt(d,f,lines) {
    if (!lines.length) throw Error("Thêm ít nhất một mặt hàng.");
    const receipt={id:id(),code:"PN"+String(d.receipts.length+1).padStart(6,"0"),at:nativeNow(),receivedOn:f.receivedOn,
      supplier:receiptSupplier(d,f),cost:total(lines,l=>l.total),lines:[]};
    recordOutgoing(receipt,f.payMode==="partial"?Number(f.outAmount):receipt.cost,f.outMethod,true);
    const retailChanges=new Map();
    const refs=priorPrices(d,f.receivedOn);
    for(const l of lines){
      const p=d.products.find(p=>p.id===l.product);
      if (!p || p.archived) throw Error("Sản phẩm không còn trong danh mục.");
      p.lots.push({id:id(),code:"Lô "+(p.lots.length+1),qty:l.base});
      if (l.newRetail != null) {
        if (!Number.isSafeInteger(l.newRetail) || l.newRetail<1) throw Error("Giá bán mới phải là số nguyên dương.");
        if (retailChanges.has(p.id) && retailChanges.get(p.id)!==l.newRetail) throw Error("Các dòng cùng quy cách đang có hai giá bán mới khác nhau.");
        retailChanges.set(p.id,l.newRetail);
      }
      const prior=priorPrice(refs.get(p.id),p,!!p.pack && l.unit===p.pack);
      receipt.lines.push({prior,product:p.id,name:variantName(p),quantity:l.quantity,unit:l.unit,width:l.width,price:l.price,qty:l.base,cost:l.total});
    }
    for (const [key,price] of retailChanges) d.products.find(p=>p.id===key).price=price;
    d.receipts.push(receipt);
  }
  let historySupplier = "";
  function receiptHistory() {
    const prefix = receiptPeriod === "all" ? "" : receiptAnchor.slice(0, {day:10, month:7, year:4}[receiptPeriod]);
    const rows = [...db.receipts].reverse().filter(r => receiptDay(r).startsWith(prefix) && (!historySupplier || (r.supplier?.id || "none") === historySupplier)).sort((a,b) => receiptDay(b).localeCompare(receiptDay(a)));
    const types = [["all","Tất cả"],["day","Ngày"],["month","Tháng"],["year","Năm"]];
    const control = types.map(([k,t]) => button(t,"receiptPeriod:"+k,"chip "+(receiptPeriod===k?"on":""))).join("");
    const dateInput = receiptPeriod === "all" ? "" : field("Chọn "+types.find(x=>x[0]===receiptPeriod)[1].toLowerCase(),"receiptAnchor",
      {day:"date",month:"month",year:"number"}[receiptPeriod],prefix,receiptPeriod==="year"?'min="1000" max="9999"':"required");
    const choices = [["", "Tất cả nhà cung cấp"], ["none", "Chưa ghi nhà cung cấp"],
      ...(db.suppliers || []).map(v => [v.id, v.name + (v.phone ? " · " + v.phone : "")])];
    const supplierFilter = sel("Lọc theo nhà cung cấp", "historySupplier", choices.map(([key, label]) =>
      '<option value="' + esc(key) + '"' + (key === historySupplier ? " selected" : "") + '>' + esc(label) + '</option>').join(""));
    return panel("Lịch sử nhập hàng", '<div class="period space">'+control+'</div><div class="forms">'+dateInput+supplierFilter+'</div>' +
      '<div class="receipt-list">'+table(["Phiếu nhập","Ngày nhập","Nhà cung cấp","Tổng tiền","Còn nợ"], rows.map(r => [
        button(esc(r.code || "Xem phiếu"),"receiptPay:"+r.id,"link")+'<small>'+num(receiptLines(r).length)+' dòng hàng</small>',
        receiptDay(r).split("-").reverse().join("/"), esc(r.supplier?.name || "Chưa ghi"), money(r.cost),
        r.outgoing ? (balance(r) ? button(money(balance(r))+" · Trả nợ","receiptPay:"+r.id,"link") : "0 ₫") :
          button("Bổ sung","receiptPay:"+r.id,"link")
      ]),"Không có phiếu nhập khớp với bộ lọc.")+'</div>');
  }
  function supplierDebts() {
    const groups = new Map();
    for (const r of db.receipts) {
      if (!r.outgoing || !r.supplier || balance(r) <= 0) continue;
      const g = groups.get(r.supplier.id) || {name:r.supplier.name,due:0,receipts:[]};
      g.due += balance(r); g.receipts.push(r); groups.set(r.supplier.id,g);
    }
    const list = [...groups.values()];
    return panel("Công nợ nhà cung cấp", '<p>Tổng còn phải trả đã ghi nhận · <b>'+money(total(list,g=>g.due))+'</b></p>'+table(
      ["Nhà cung cấp","Còn phải trả","Phiếu đang nợ"],list.map(g=>[esc(g.name),money(g.due),g.receipts.map(r=>
        button(receiptDay(r).split("-").reverse().join("/")+" · "+esc(receiptTitle(r))+" · "+money(balance(r)), "receiptPay:"+r.id,"link")).join(" ")]),"Chưa có khoản nợ đã ghi nhận."));
  }
  function paymentDetail(r) {
    const initial = !r.outgoing;
    const due = initial ? r.cost : balance(r);
    const contact = [r.supplier?.phone,r.supplier?.address].filter(Boolean).map(esc).join(" · ");
    let body = '<p class="summary"><b>'+esc(r.supplier?.name || "Chưa ghi nhà cung cấp")+'</b> · '+receiptDay(r).split("-").reverse().join("/")+
      (contact ? "<br>"+contact : "")+'<br>Giá trị nhập <b>'+money(r.cost)+'</b></p>';
    body += '<h2>Chi tiết mặt hàng ('+receiptLines(r).length+')</h2><div class="receipt-items">'+table(["Sản phẩm","Số lượng","Giá nhập","Thành tiền"],receiptLines(r).map(l=>[esc(itemName(l)),num(l.quantity)+" "+esc(l.unit),l.price==null?"—":money(l.price)+" / "+esc(l.width?"m²":l.unit)+(l.prior?"<br><small>"+esc(priceChange(l.prior.price,l.price))+"</small>":""),money(l.cost)]))+'</div>';
    if (!initial) body += '<p>Đã trả '+money(supplierPaid(r))+' · Còn nợ '+money(due)+'</p>'+table(["Thời gian ghi nhận","Nội dung","Phương thức","Số tiền"],r.outgoing.map(p=>[time(p.at),p.initial?"Đã trả ban đầu":"Trả nợ",esc(p.method),money(p.amount)]));
    if (initial || due) {
      const assign = initial && !r.supplier ? sel("Nhà cung cấp","supplier", opt("","Chưa chọn")+opt("new","Thêm cơ sở mới")+(db.suppliers||[]).map(v=>opt(v.id,v.name)))+
        field("Tên cơ sở (nếu thêm mới)","supplierName","text","","") : "";
      body += form("receiptPayment",field("","receiptId","hidden",r.id)+assign+'<div class="forms">'+
        field(initial?"Tổng đã trả cho phiếu này (₫)":"Trả thêm lần này (₫)","outAmount","number",initial?"":due,'required min="'+(initial?0:1)+'" max="'+due+'" step="1"')+
        paymentMethod()+'</div>',initial?"Lưu thanh toán ban đầu":"Ghi nhận trả nợ");
    }
    modal(esc(r.code || "Chi tiết phiếu nhập"),body);
  }
  function trade(selling) {
    let desc = selling ? "Chọn sản phẩm, kiểm tra tồn kho rồi thanh toán." : "Ghi nhận số lượng, đơn vị nhập và giá nhập thực tế.";
    let body = head("QUẦY GIAO DỊCH", page, desc, staff?"":button("＋ Thêm sản phẩm", "newproduct"));
    if(selling){
      const tabs=orderTabs();
      if(!tabs.length)tabs.push(blankOrder());
      const tab=tabs.find(t=>t.id===activeOrder)||tabs[0];
      activateOrder(tab);
      body+=orderStrip(tabs);
      if(tab.sale)return body+panel(esc(tab.label)+" · Đã hoàn thành",'<p>Đã lập hóa đơn '+esc(tab.code)+'.</p>'+button("Xem hóa đơn","invoice:"+tab.sale));
    }
    if (activeProducts().length && !selling) body += panel("Lập phiếu nhập",form("receive",receiptHeader()+
      '<div id="intakeRows">'+intakeRow()+'</div>'+button("＋ Thêm dòng hàng","addIntake")+
      '<p class="summary space" id="intakeTotal">Tổng phiếu nhập · 0 ₫</p><div class="forms">'+sel("Thanh toán nhà cung cấp","payMode",opt("full","Trả đủ")+opt("partial","Trả một phần / ghi nợ"))+paymentMethod()+'</div><div id="initialOut"></div>',"Xác nhận nhập kho"));
    else if (activeProducts().length) body += panel("Thêm vào đơn hàng",form("line",'<div class="forms">'+productPicker("product")+'<div id="units"></div></div><div id="tradeFields"></div>',"＋ Thêm vào đơn"));else if (staff) body += panel("Danh mục đang trống","Chưa có sản phẩm để bán.");else body += panel("Danh mục đang trống", '<p class="space">Tạo sản phẩm đầu tiên để chọn đơn vị và giá bán.</p>' + button("Thêm sản phẩm", "newproduct", "link"));
    if (selling) return body + panel(esc(held?.label||blankOrder().label), table(["Sản phẩm", "Số lượng", "Thành tiền", ""], cart.map((l, i) => [esc(l.name), lineQty(l), money(l.total), button("Xóa", "remove:" + i, "link")]), "Đơn hàng đang trống.") + '<div class="row space"><b>Tổng cộng · ' + money(total(cart, l => l.total)) + '</b>' + (cart.length ? actions("Thanh toán →", "checkout") : "") + '</div>');
    return body;
  }
  function tradeFields(reset) {
    const p = product($('[name=product]').value),
      selling = page === "Bán hàng";
    if (reset) $("#units").innerHTML = sel("Đơn vị giao dịch", "unit", opt("base", p.unit) + (p.pack ? opt("pack", p.pack) : ""));
    const factor = $('[name=unit]').value === "pack" ? p.factor : 1;
    $("#tradeFields").innerHTML = '<div class="forms">' + (selling && p.width ? sel("Chọn cuộn cần cắt", "lot", p.lots.filter(l => l.qty > 0).map(l => opt(l.id, l.code + " · còn " + num(l.qty) + " m")).join("")) : "") + field(p.width ? selling ? "Chiều dài cần cắt (m)" : "Chiều dài cuộn nhập (m)" : "Số lượng", "quantity", "number", "1", "required min=0.001 step=0.001") + retailField(p,"price","Giá bán / "+esc(p.width?"m²":$('[name=unit]').value==="pack"?p.pack:p.unit)+" (₫)",Math.round(p.price*factor),"required min=0 step=1",$('[name=unit]').value==="pack") + '</div><p class="summary" id="calc"></p>';
    calc();
  }
  function calc() {
    const p = product($('[name=product]').value),
      q = Number(inputValue($('[name=quantity]'))),
      v = Number(inputValue($('[name=price]')));
    saleCostHint();
    $("#calc").textContent = (p.width ? 'Khổ ' + num(p.width) + ' m × ' + num(q) + ' m = ' + num(round(q * p.width)) + ' m² · ' : "") + 'Thành tiền ' + money(Math.round(q * (p.width || 1) * v));
  }
  const lineQty = l => num(l.quantity) + " " + esc(l.unit) + (l.width ? " × " + num(l.width) + " m = " + num(round(l.quantity * l.width)) + " m²" : "");
  function makeLine(f) {
    const p = product(f.product),
      factor = f.unit === "pack" ? p.factor : 1,
      quantity = Number(f.quantity),
      price = Number(f.price),
      base = round(quantity * factor),
      width = p.width;
    if (!(quantity > 0 && price >= 0 && base > 0)) throw Error("Kiểm tra số lượng và đơn giá.");
    return {
      product: p.id,
      name: variantName(p),
      quantity,
      unit: f.unit === "pack" ? p.pack : p.unit,
      base,
      price,
      width,
      lot: f.lot || "",
      total: Math.round(quantity * (width || 1) * price)
    };
  }
  function consume(d, line) {
    let p = d.products.find(p => p.id === line.product),
      left = line.base;
    if (!p || p.archived) throw Error("Sản phẩm đã bị xóa khỏi danh mục. Vui lòng bỏ dòng này khỏi đơn.");
    for (const l of p.lots) {
      if (p.width && l.id !== line.lot) continue;
      const take = Math.min(left, l.qty);
      l.qty = round(l.qty - take);
      left = round(left - take);
      if (!left) break;
    }
    if (left > 0) throw Error("Không đủ tồn kho cho " + p.name + ". Kiểm tra số lượng hoặc chọn cuộn khác.");
  }
