  let previousPage = "";
  function animateWorkspace() {
    const entering = page !== previousPage;
    previousPage = page;
    const wrap = root.querySelector("main .wrap");
    if (!entering || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const blocks = wrap.querySelectorAll(".head, .profit-hero, .tile, .panel");
    blocks.forEach((block,index)=>{
      block.classList.add("workspace-block");
      block.style.setProperty("--enter-delay", Math.min(index,9)*42+"ms");
    });
    wrap.querySelectorAll(".bar").forEach((bar,index)=>{
      bar.classList.add("workspace-bar");
      bar.style.setProperty("--bar-delay", (210+index*9)+"ms");
    });
    const figures = Array.from(wrap.querySelectorAll(".tile strong, .profit-hero strong")).flatMap(el=>{
      const original=el.textContent;
      const match=/^(-?[\d.]+)( ₫)?$/.exec(original);
      if (!match) return [];
      const target=Number(match[1].replaceAll(".",""));
      return Number.isSafeInteger(target) && target!==0 ? [{el,target,original,suffix:match[2]||""}] : [];
    });
    if (!figures.length) return;
    const start=performance.now();
    function tick(now) {
      if (!wrap.isConnected) return;
      const progress=Math.min(1,Math.max(0,(now-start)/580));
      const eased=1-(1-progress)**3;
      for (const {el,target,original,suffix} of figures) {
        el.textContent=progress===1 ? original : num(Math.round(target*eased))+suffix;
      }
      if (progress<1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }
